+const INFERENCE_HEALTH_SERVICE: &str = "inference";
+const LIVENESS_HEALTH_SERVICE: &str = "liveness";
+const HEALTH_SERVICES: [&str; 2] = [INFERENCE_HEALTH_SERVICE, LIVENESS_HEALTH_SERVICE];
